    for idx, rt in enumerate(route):
        for node in rt:
            pos_route[node] = idx
        rload.append(sum(demands[x] for x in rt))

    unassigned = [c for c in cust_ids if c not in pos_route]
    if unassigned:
        # Insert each unassigned into best feasible route by cheapest insertion
        for c in unassigned:
            best_r = None
            best_pos = None
            best_delta = None
            dc = demands[c]
            for ri in range(len(route)):
                if rload[ri] + dc > cap:
                    continue
                rt = route[ri]
                # try positions: between nodes and ends
                m = len(rt)
                for pos in range(m + 1):
                    # insert at pos
                    if m == 0:
                        delta = d(depot, c) + d(c, depot)
                    else:
                        if pos == 0:
                            delta = d(depot, c) + d(c, rt[0]) - d(depot, rt[0])
                        elif pos == m:
                            delta = d(rt[-1], c) + d(c, depot) - d(rt[-1], depot)
                        else:
                            a = rt[pos - 1]
                            b = rt[pos]
                            delta = d(a, c) + d(c, b) - d(a, b)
                    if best_delta is None or delta < best_delta or (delta == best_delta and ri < best_r):
                        best_delta = delta
                        best_r = ri
                        best_pos = pos
            if best_r is None:
                # create new route (feasible since singleton)
                route.append([c])
                pos_route[c] = len(route) - 1
                rload.append(dc)
            else:
                route[best_r].insert(best_pos, c)
                pos_route[c] = best_r
                rload[best_r] += dc

    # Post-reduction if too many routes: deterministically relocate nodes from smallest routes
    # to reduce route count <= veh_hint (as feasible as possible)
    def feasible_insertion_delta(rt, c, pos):
        m = len(rt)
        if m == 0:
            return d(depot, c) + d(c, depot)
        if pos == 0:
            return d(depot, c) + d(c, rt[0]) - d(depot, rt[0])
        if pos == m:
            return d(rt[-1], c) + d(c, depot) - d(rt[-1], depot)
        a = rt[pos - 1]
        b = rt[pos]
        return d(a, c) + d(c, b) - d(a, b)

    def try_relocate_one():
        # best feasible relocate move (first improvement deterministic via scanning order)
        base_cost = total_cost()
        best_move = None  # (delta_total, from_r, to_r, node, from_pos, to_pos)
        for fr in range(len(route)):
            rtA = route[fr]
            if len(rtA) <= 1:
                continue
            # Try each node in A
            for i, node in enumerate(rtA):
                tr_dem = demands[node]
                for to in range(len(route)):
                    if to == fr:
                        continue
                    if rload[to] + tr_dem > cap:
                        continue
                    rtB = route[to]
                    # compute removal impact on A and insertion impact on B
                    # delta in cost:
                    # remove node at position i from A
                    mA = len(rtA)
                    if mA == 1:
                        delta_rem = -(d(depot, node) + d(node, depot))
                    else:
                        if i == 0:
                            # depot->node->next replaced with depot->next
                            nxt = rtA[1]
                            delta_rem = d(depot, nxt) - (d(depot, node) + d(node, nxt))
                        elif i == mA - 1:
                            prev = rtA[mA - 2]
                            delta_rem = d(prev, depot) - (d(prev, node) + d(node, depot))
                        else:
                            prev = rtA[i - 1]
                            nxt = rtA[i + 1]
                            delta_rem = d(prev, nxt) - (d(prev, node) + d(node, nxt))
                    # Try insertion positions in B (including ends)
                    mB = len(rtB)
                    best_ins = None
                    best_delta_ins = None
                    for pos in range(mB + 1):
                        delta_ins = feasible_insertion_delta(rtB, node, pos)
                        if best_delta_ins is None or delta_ins < best_delta_ins:
                            best_delta_ins = delta_ins
                            best_ins = pos
                    if best_ins is None:
                        continue
                    delta_total = delta_rem + best_delta_ins
                    if delta_total < 0:
                        best_move = (delta_total, fr, to, node, i, best_ins)
                        return
